"""Render one page through its template with site-wide context."""
from __future__ import annotations

from quillpress.content import Page
from quillpress.templates import TemplateSet


class Renderer:
    def __init__(self, templates: TemplateSet, pages: list[Page]):
        self.templates = templates
        self.pages = pages
        self.by_tag = {}
        for page in pages:
            for tag in page.tags:
                self.by_tag.setdefault(tag, []).append(page)

    def context(self, page: Page) -> dict:
        return {
            'page': page,
            'pages': self.pages,
            'related': [p for tag in page.tags for p in self.by_tag[tag] if p is not page],
            'recent': sorted(self.pages, key=lambda p: p.date, reverse=True)[:10],
        }

    def render(self, page: Page) -> str:
        template = self.templates.get(page.layout)
        return template.render(**self.context(page))

