from __future__ import annotations

import hashlib
import json
from dataclasses import asdict, dataclass, field
from pathlib import Path


def file_hash(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()[:16]


@dataclass
class Entry:
    output: str
    inputs: dict[str, str] = field(default_factory=dict)
    site_dependent: bool = False


class Manifest:
    def __init__(self, path: Path):
        self.path = path
        self.entries: dict[str, Entry] = {}
        self.content_hash = ''
        if path.exists():
            raw = json.loads(path.read_text())
            self.content_hash = raw.get('content_hash', '')
            self.entries = {k: Entry(**v) for k, v in raw.get('entries', {}).items()}

    def save(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.path.write_text(json.dumps({
            'content_hash': self.content_hash,
            'entries': {k: asdict(v) for k, v in self.entries.items()},
        }, indent=1, sort_keys=True))

    def is_stale(self, output: str, inputs: dict[str, str], content_changed: bool) -> bool:
        entry = self.entries.get(output)
        if entry is None or entry.inputs != inputs:
            return True
        return entry.site_dependent and content_changed
