"""Subscribe to the broker and write readings as they arrive."""
from __future__ import annotations

import datetime as dt
import json

from driftwatch.db import connect
from driftwatch.parse import parse_payload


def store(conn, sensor_id: str, payload: bytes) -> int:
    rows = parse_payload(sensor_id, payload)
    now = dt.datetime.now(dt.timezone.utc).isoformat()
    conn.executemany(
        'insert into readings (sensor_id, observed_at, metric, value, received_at)'
        ' values (?, ?, ?, ?, ?)',
        [(r.sensor_id, r.observed_at, r.metric, r.value, now) for r in rows],
    )
    conn.commit()
    return len(rows)


def on_message(client, userdata, message):
    sensor_id = message.topic.rsplit('/', 1)[-1]
    with connect() as conn:
        store(conn, sensor_id, message.payload)

